  assert.equal(res.headers.get('content-type'), 'application/json')
  assert.equal(typeof json.id, 'string')
  assert.deepEqual(json, { id: json.id, items: [{ sku: 'A', qty: 2 }], total: 20 })
})

test('POST /orders ids are sequential strings', async () => {
  const a = (await post({ items: [{ sku: 'A', qty: 1 }] })).json.id
  const b = (await post({ items: [{ sku: 'A', qty: 1 }] })).json.id
  assert.equal(Number(b), Number(a) + 1)
})

test('POST /orders sums several items', async () => {
  const { json } = await post({ items: [{ sku: 'A', qty: 1 }, { sku: 'B', qty: 2 }] })
  assert.equal(json.total, 110 - 11)
})

test('POST /orders: total of exactly 100 gets no discount', async () => {
  assert.equal((await post({ items: [{ sku: 'B', qty: 2 }] })).json.total, 100)
})

test('POST /orders: total above 100 gets 10% discount, floored', async () => {
  assert.equal((await post({ items: [{ sku: 'C', qty: 1 }] })).json.total, 90) // 90.9 -> 90
})

test('POST /orders: fractional total is floored', async () => {
  assert.equal((await post({ items: [{ sku: 'D', qty: 3 }] })).json.total, 1)
})

test('POST /orders: extra item fields are echoed back', async () => {
  const { json } = await post({ items: [{ sku: 'A', qty: 1, note: 'x' }] })
  assert.deepEqual(json.items, [{ sku: 'A', qty: 1, note: 'x' }])
})

test('POST /orders 400 when items missing', async () => {
  const { res, json } = await post({})
  assert.equal(res.status, 400)
  assert.deepEqual(json, { error: 'items required' })
})

test('POST /orders 400 when items empty', async () => {
  const { res, json } = await post({ items: [] })
  assert.equal(res.status, 400)
  assert.deepEqual(json, { error: 'items required' })
})

test('POST /orders 400 when items is not an array', async () => {
  assert.equal((await post({ items: 'A' })).res.status, 400)
})

test('POST /orders 400 on invalid JSON', async () => {
  const { res, json } = await post(undefined, '{nope')
  assert.equal(res.status, 400)
  assert.deepEqual(json, { error: 'items required' })
})

test('POST /orders 400 on empty body', async () => {
  assert.equal((await post(undefined, '')).res.status, 400)
})

test('POST /orders with unknown sku or missing qty yields 201 with total null', async () => {
  // CHARACTERIZATION: current behaviour may be unintended — no item validation; NaN total serialises as null.
  const unknown = await post({ items: [{ sku: 'ZZZ', qty: 1 }] })
  assert.equal(unknown.res.status, 201)
  assert.equal(unknown.json.total, null)
  const noQty = await post({ items: [{ sku: 'A' }] })
  assert.equal(noQty.res.status, 201)
  assert.equal(noQty.json.total, null)
})

test('GET /orders/:id returns a created order', async () => {
