  const { res, json } = await call('GET', `/orders/${created.id}`)
  assert.equal(res.status, 200)
  assert.equal(res.headers.get('content-type'), 'application/json')
  assert.deepEqual(json, created)
})

test('GET /orders/:id for unknown id returns 200 with error body', async () => {
  // CHARACTERIZATION: current behaviour may be unintended — missing order answers 200, not 404.
  const { res, json } = await call('GET', '/orders/does-not-exist')
  assert.equal(res.status, 200)
  assert.deepEqual(json, { error: 'not found' })
})

test('GET /orders/:id ignores query string', async () => {
